    "C07J41/0033": {
      "code": "C07J41/0033",
      "level": 8,
      "parent": "C07J41/00",
      "ja": "｛Ｃ０７Ｊ４１／０００５に含まれないもの｝　．｛注．．グループ　Ｃ０７Ｊ４１／００３８～Ｃ０７Ｊ４１／００９４において，ステロイド骨格の１７－β位の置換基に関する全ての事項は，１７位に二重結合があるときは，１７位の置換基を含み，アミド基に関する事項は全ての窒素置換カルボニル基を含む　｝",
      "en": "{not covered by C07J41/0005}<br><br><u>NOTE</u><br><br> In groups C07J41/0038&#160;-&#160;C07J41/0094 all references to substituents in position 17-beta of the steroid skeleton include substituents at the 17-position when there is a double bond to or from position 17, and all references to an amide group include all nitrogen substituted carbonyl groups. ",
      "count": 80,
      "ipcCode": "C07J41/00",
      "coreCode": "C07J41/00",
      "note": "",
      "sourceFile": "cpc_C07J.txt",
      "kind": "cpc"
    },
